using System.Collections.Generic;

namespace TAX.HTKK.Utilities.Core;

public class HTKKDictionaryDiaDanh
{
	public Dictionary<string, string> dicQuocTich = new Dictionary<string, string>();

	public Dictionary<string, string> dicQuanHe = new Dictionary<string, string>();

	public Dictionary<string, string> dicTinhTP = new Dictionary<string, string>();

	public Dictionary<string, string> dicQuanHuyen = new Dictionary<string, string>();

	public Dictionary<string, string> dicQuanHuyenByTinhTP = new Dictionary<string, string>();

	public Dictionary<string, string> dicPhuongXaByQuanHuyen = new Dictionary<string, string>();

	public Dictionary<string, string> dicPhuongXa = new Dictionary<string, string>();

	public HTKKDictionaryDiaDanh()
	{
		CreateQuanHe();
		CreateQuocTich();
		CreateTinhTP();
		CreateQuanHuyen();
		CreateQuanHuyenByTinhTP();
		CreatePhuongXaByQuanHuyen();
		CreatePhuongXa();
	}

	public Dictionary<string, string> getQuanHuyen(string keyTinhTP)
	{
		Dictionary<string, string> dictionary = new Dictionary<string, string>();
		foreach (KeyValuePair<string, string> item in dicQuanHuyen)
		{
			if (item.Key.Substring(0, 3).Equals(keyTinhTP))
			{
				dictionary.Add(item.Key, item.Value);
			}
		}
		return dictionary;
	}

	public Dictionary<string, string> getPhuongXa(string KeyQuanHuyen)
	{
		Dictionary<string, string> dictionary = new Dictionary<string, string>();
		foreach (KeyValuePair<string, string> item in dicPhuongXa)
		{
			if (item.Key.Substring(0, 5).Equals(KeyQuanHuyen))
			{
				dictionary.Add(item.Key, item.Value);
			}
		}
		return dictionary;
	}

	private void CreateQuocTich()
	{
		dicQuocTich.Add("01", "Việt Nam");
		dicQuocTich.Add("02", "Khác");
	}

